/** Get MLA profile by constituency number */
export function getTNMLAProfile(acNo: number): MLAProfile | undefined {
  return TN_MLA_PROFILES.find((p) => p.acNo === acNo);
}

/** Get all MLA profiles */
export function getAllTNMLAs(): MLAProfile[] {
  return TN_MLA_PROFILES;
}
